public void write()
{
    FormDataSource formDs = this;

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        GUPFreeItemLine freeItemLine = formDs.cursor();

        FormRun formRun = this.formRun();
        InventDim freeItemLineInventDim = formRun.dataSource(formdatasourcestr(RetailPeriodicDiscount, GUPFreeItemLineInventDim)).cursor();
        freeItemLine.InventDimId = InventDim::findOrCreate(freeItemLineInventDim).inventDimId;
    }

    next write();

    this.research(true);
}
